DROP TABLE IF EXISTS metadata;
DROP TABLE IF EXISTS datasets;
DROP TABLE IF EXISTS boundary_levels;
DROP TABLE IF EXISTS entities;
DROP TABLE IF EXISTS entity_tags;
DROP TABLE IF EXISTS trails;
CREATE TABLE boundary_levels (
          level TEXT PRIMARY KEY,
          level_name TEXT NOT NULL,
          name_zh TEXT,
          name_en TEXT,
          area_ha_official REAL,
          geometry_status TEXT NOT NULL,
          geometry_json TEXT,
          geometry_url TEXT,
          bbox_west REAL,
          bbox_south REAL,
          bbox_east REAL,
          bbox_north REAL,
          source TEXT,
          source_license TEXT,
          metadata_json TEXT
        );
CREATE TABLE datasets (
          dataset_id TEXT PRIMARY KEY,
          kind TEXT NOT NULL,
          title TEXT NOT NULL,
          source_path TEXT,
          public_url TEXT,
          source_license TEXT,
          attribution TEXT,
          status TEXT NOT NULL,
          metadata_json TEXT
        );
CREATE TABLE entities (
          entity_id TEXT PRIMARY KEY,
          osm_type TEXT NOT NULL,
          osm_id INTEGER NOT NULL,
          name TEXT,
          name_zh TEXT,
          name_en TEXT,
          category TEXT NOT NULL,
          subtype TEXT,
          lon REAL NOT NULL,
          lat REAL NOT NULL,
          scope_level TEXT NOT NULL,
          scope_note TEXT,
          elevation_m REAL,
          elevation_source TEXT,
          elevation_confidence REAL,
          dem_elevation_m REAL,
          osm_dem_delta_m REAL,
          osm_ele_raw TEXT,
          source TEXT NOT NULL,
          source_license TEXT NOT NULL,
          source_rank INTEGER NOT NULL,
          search_text TEXT
        );
CREATE TABLE entity_tags (
          entity_id TEXT NOT NULL,
          key TEXT NOT NULL,
          value TEXT NOT NULL,
          PRIMARY KEY (entity_id, key)
        );
CREATE TABLE metadata (
          key TEXT PRIMARY KEY,
          value TEXT NOT NULL
        );
CREATE TABLE trails (
          trail_id TEXT PRIMARY KEY,
          osm_type TEXT NOT NULL,
          osm_id INTEGER NOT NULL,
          name TEXT,
          highway TEXT,
          surface TEXT,
          access TEXT,
          width TEXT,
          incline TEXT,
          scope_level TEXT NOT NULL,
          scope_note TEXT,
          node_count INTEGER NOT NULL,
          geometry_json TEXT NOT NULL,
          elevation_status TEXT NOT NULL,
          elevation_source TEXT,
          length_m REAL,
          elevation_min_m REAL,
          elevation_max_m REAL,
          elevation_start_m REAL,
          elevation_end_m REAL,
          ascent_m REAL,
          descent_m REAL,
          sample_count INTEGER,
          profile_json TEXT,
          source TEXT NOT NULL,
          source_license TEXT NOT NULL
        );
CREATE INDEX idx_entities_scope_category ON entities(scope_level, category, subtype);
CREATE INDEX idx_entities_lon_lat ON entities(lon, lat);
CREATE INDEX idx_entities_name ON entities(name);
CREATE INDEX idx_entities_osm ON entities(osm_type, osm_id);
CREATE INDEX idx_entity_tags_key_value ON entity_tags(key, value);
CREATE INDEX idx_trails_scope ON trails(scope_level);
